var EXTRA=[{"dot": "gray", "j": "Arthroscopy", "h": "Riparazione del LCA: l'editoriale invita a sceglierne bene i candidati", "v": "Commento di opinione: l'autore tiene la ricostruzione come riferimento e lega i fallimenti della riparazione all'età giovane e a una guaina sinoviale poco conservata; non porta dati propri.", "pmid": "42847898", "doi": "10.1002/arj.70687", "temi": ["riparazione del LCA", "guaina sinoviale", "editoriale"]}, {"dot": "gray", "j": "EFORT Open Reviews", "h": "Protesi parziale da un lato e totale dall'altro: revisione sistematica", "v": "L'abstract non è disponibile in PubMed: del lavoro si conoscono solo titolo, rivista e autori (fra loro D'Ambrosi); il contenuto non è verificato.", "pmid": "42825407", "doi": "10.1530/EOR-2025-0193", "temi": ["UKA", "TKA", "artrosi bilaterale"]}, {"dot": "gray", "j": "Knee Surg Sports Traumatol Arthrosc", "h": "Il disallineamento del quadricipite come motore dello squilibrio femororotuleo", "v": "L'abstract non è disponibile in PubMed: del lavoro si conosce solo il titolo; il contenuto non è verificato.", "pmid": "42841796", "doi": "10.1002/ksa.70634", "temi": ["rotula", "quadricipite", "femororotuleo"]}, {"dot": "gray", "j": "The Journal of Arthroplasty", "h": "Cerniera rotante nella protesi totale: primarie e revisioni analizzate separatamente", "v": "Coorte retrospettiva monocentrica che separa i due contesti, con risultati funzionali buoni in entrambi; senza gruppo di confronto non dice se la cerniera sia la causa del risultato.", "pmid": "42843681", "doi": "10.1016/j.arth.2026.09.042", "temi": ["protesi a cerniera", "revisione", "TKA"]}, {"dot": "gray", "j": "Clinical Case Reports", "h": "Lacerazione isolata della capsula posteromediale in un adolescente: caso singolo", "v": "Riparata in artroscopia, con lieve recurvato residuo a distanza di mesi; gli autori la accostano alle lesioni ramp e chiedono studi: un caso non fonda un'indicazione.", "pmid": "42840640", "doi": "10.1002/ccr3.73686", "temi": ["capsula posteromediale", "adolescente", "caso clinico"]}, {"dot": "gray", "j": "Trauma Case Reports", "h": "Monopattino elettrico e spina tibiale: una frattura sottile in una adolescente", "v": "Caso singolo: le radiografie iniziali erano state lette come normali e la TAC ha mostrato l'avulsione con estensione alla fisi, trattata senza intervento; promemoria diagnostico, non evidenza.", "pmid": "42840513", "doi": "10.1016/j.tcr.2026.101438", "temi": ["spina tibiale", "adolescente", "LCA pediatrico"]}, {"dot": "gray", "j": "BMC Musculoskeletal Disorders", "h": "Controllo sensomotorio dopo LCA: il punto di vista dei fisioterapisti", "v": "Studio qualitativo con focus group di fisioterapisti esperti su come sensori, realtà virtuale e intelligenza artificiale potrebbero sostenere valutazione e riabilitazione; raccoglie opinioni, non misura esiti.", "pmid": "42844609", "doi": "10.1186/s12891-026-10484-x", "temi": ["riabilitazione LCA", "controllo sensomotorio", "tecnologia"]}, {"dot": "gray", "j": "Frontiers in Bioengineering and Biotechnology", "h": "Cerniera rotante contro protesi a sfera e cavità: un confronto al computer", "v": "Simulazione agli elementi finiti di due protesi vincolate per cinematica, pressioni di contatto e usura del polietilene; non è uno studio su pazienti e non dice nulla sulla durata clinica.", "pmid": "42846074", "doi": "10.3389/fbioe.2026.1942105", "temi": ["protesi vincolata", "usura", "biomeccanica"]}, {"dot": "gray", "j": "Journal of Bone and Joint Surgery (Am)", "h": "Proiezioni globali sulle revisioni protesiche: un commento prudente", "v": "L'abstract non è disponibile in PubMed: del lavoro si conoscono solo titolo e autore del commento; il contenuto non è verificato.", "pmid": "42842641", "doi": "10.2106/JBJS.26.01107", "temi": ["revisione protesica", "registri", "proiezioni"]}, {"dot": "gray", "j": "The Journal of Arthroplasty", "h": "Inginocchiarsi dopo la protesi totale: contano le abitudini prima dell'intervento", "v": "Questionario telefonico in una coorte retrospettiva: più attività fisica prima dell'operazione si associa a più inginocchiamento prima e dopo; sono associazioni, non cause.", "pmid": "42843684", "doi": "10.1016/j.arth.2026.09.048", "temi": ["protesi totale", "inginocchiarsi", "esiti riferiti dal paziente"]}];
var SCOPERTE=[{"t": "L'intelligenza artificiale in ortopedia va costruita con i chirurghi, non solo per loro", "v": "Editoriale ESSKA su KSSTA (Oettl, Zsidai, Musahl, Zaffagnini e altri): sostiene che la differenza durevole fra sistemi non sta nell'architettura del modello ma in chi controlla il ciclo di aggiornamento, cioè chi può riaddestrarlo sui risultati locali, verificarne gli errori e ritirarlo quando deriva. È opinione di esperti, senza dati propri. Vale la deviazione perché sposta la domanda da «quale IA?» a «chi ne risponde?».", "pmid": "42811872", "doi": "10.1002/ksa.70628", "temi": ["intelligenza artificiale", "responsabilità del chirurgo", "editoriale"]}, {"t": "Agopuntura con ago caldo nell'artrosi del ginocchio: conta la frequenza delle sedute?", "v": "RCT cinese su 84 pazienti (Pain Research and Management): cinque sedute a settimana contro due per due settimane; differenza del dolore WOMAC fra i gruppi 3,07 (IC 95% da 1,86 a 4,28; p<0,001), con il segno clinico non esplicitato nell'abstract. Confronta due dosi della stessa terapia, senza gruppo placebo: non dice se l'ago caldo funzioni. Vale la deviazione perché mostra come la medicina tradizionale cinese viene studiata con scale occidentali.", "pmid": "42841454", "doi": "10.1155/prm/1674261", "temi": ["agopuntura", "medicina tradizionale cinese", "artrosi"]}, {"t": "Il menisco letto cellula per cellula: che cosa insegna il sequenziamento a singola cellula", "v": "Revisione narrativa (Connective Tissue Research): descrive popolazioni cellulari del menisco e il loro ruolo in omeostasi, degenerazione e riparazione; gli stessi autori elencano gli ostacoli alla traduzione clinica, fra cui matrice densa, cellule difficili da isolare, differenze fra specie e perdita dell'informazione spaziale. Vale la deviazione perché è la base su cui potrebbero poggiare future terapie meniscali; oggi non ha ricadute operative.", "pmid": "42841355", "doi": "10.1080/03008207.2026.2739996", "temi": ["menisco", "biologia cellulare", "bioingegneria"]}];
var SOC={"1": {"video": "Quando si rompe la radice posteriore del menisco interno, la si può riattaccare con una sutura. Un gruppo del Minnesota ha studiato con una risonanza ad altissimo campo 25 pazienti, prima dell'intervento e dopo 6 mesi.\n\nLe suture risultavano integre in tutti, ma il menisco si era comunque spostato verso l'esterno: in media da 3,7 a 4,9 millimetri. Più il tessuto appariva alterato prima dell'intervento, maggiore era lo spostamento.\n\nIl limite: sono 25 pazienti in un solo centro, con un controllo a 6 mesi. Lo studio non dice come stanno dopo ginocchio e dolore, e non dimostra che lo spostamento si possa evitare.\nFonte: PubMed, PMID 42844718.", "linkedin": "Rifissazione della radice posteriore del menisco mediale: la T2* a 7 T prima della sutura correla con l'estrusione dopo (Kajabi, LaPrade e coll., J Orthop Res, ottobre 2026).\n\n25 pazienti studiati a 7 T prima e a 6 mesi dopo la rifissazione, più 9 controlli. Suture integre in tutti; estrusione mediale da 3,7 ± 1,1 a 4,9 ± 1,5 mm (p=0,002); T2* preoperatoria contro estrusione postoperatoria ρ=0,765 (p<0,001).\n\nLimiti: n=25, una sede, estrusione a 6 mesi come unico esito, nessun esito clinico nell'abstract, tecnica di sutura non riportata, intervallo di confidenza della correlazione non riportato.\nFonte: PubMed, PMID 42844718.", "instagram": "Il menisco riattaccato può spostarsi lo stesso.\nIn uno studio su 25 persone la sutura teneva a 6 mesi, ma il menisco si era spostato di più dove il tessuto era più alterato prima dell'intervento.\nÈ uno studio piccolo, senza risultati clinici.\nFonte: PubMed, PMID 42844718.", "pazienti": "Il menisco è tenuto in posizione da due radici. Quando una si rompe, si può riattaccare con una sutura.\n\nIn uno studio su 25 persone la sutura teneva dopo 6 mesi, ma il menisco si era comunque spostato un po' verso l'esterno, tanto più quanto il suo tessuto era alterato prima dell'intervento.\n\nLo studio è piccolo, dura pochi mesi e non dice come stanno le persone dopo: se ne parla con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42844718."}};
var SOCV={"1": {"video": {"chir": ["Rifissazione della radice mediale: uno studio a 7 tesla del Minnesota, con LaPrade, J Orthop Res, ottobre 2026. 25 pazienti, 9 controlli.", "Suture integre alla risonanza in tutti, ma l'estrusione mediale sale da 3,7 a 4,9 millimetri a 6 mesi (p=0,002). La T2* preoperatoria correla con l'estrusione dopo: rho 0,765, p inferiore a 0,001.", "Il limite: 25 pazienti, una sede, nessun esito clinico nell'abstract, tecnica di sutura non riportata, nessun intervallo di confidenza per la correlazione. È un biomarcatore candidato, non un criterio di scelta.\nFonte: PubMed, PMID 42844718."], "misto": ["Una squadra del Minnesota ha studiato con una risonanza ad altissimo campo 25 persone operate per la rottura della radice del menisco interno, prima e 6 mesi dopo la sutura.", "Le suture tenevano in tutti, ma il menisco si era spostato verso l'esterno, da 3,7 a 4,9 millimetri in media. Più il tessuto appariva alterato prima dell'intervento, maggiore lo spostamento.", "Il limite: pochi pazienti, un solo centro, controllo a 6 mesi e nessun dato clinico nel riassunto. Non dimostra che lo spostamento si possa evitare.\nFonte: PubMed, PMID 42844718."], "pazienti": ["Il menisco è tenuto in posizione da due radici. Quando una si rompe, si può riattaccare con una sutura.", "In uno studio su 25 persone la sutura teneva dopo 6 mesi, ma il menisco si era spostato un po' verso l'esterno, tanto più quanto il tessuto era alterato prima.", "Lo studio è piccolo e non dice come stanno le persone dopo: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42844718."]}, "linkedin": {"chir": ["MMPRT, rifissazione: T2* a 7 T preoperatoria ed estrusione postoperatoria (Kajabi, LaPrade e coll., J Orthop Res, ottobre 2026), 25 pazienti e 9 controlli.", "Suture integre in tutti; estrusione mediale da 3,7 ± 1,1 a 4,9 ± 1,5 mm (p=0,002); T2* preoperatoria contro estrusione postoperatoria ρ=0,765 (p<0,001).", "Limiti: n=25, una sede, estrusione a 6 mesi come unico esito, tecnica di sutura non riportata, nessun IC per la correlazione.\nFonte: PubMed, PMID 42844718."], "misto": ["Rottura della radice del menisco interno: uno studio con risonanza a 7 tesla su 25 pazienti prima e 6 mesi dopo la sutura (Minnesota, J Orthop Res, ottobre 2026).", "Suture integre in tutti, ma il menisco si sposta verso l'esterno da 3,7 a 4,9 mm; il valore alla risonanza prima dell'intervento è legato allo spostamento successivo.", "Limiti: pochi pazienti, un solo centro, nessun esito clinico nel riassunto.\nFonte: PubMed, PMID 42844718."], "pazienti": ["Menisco riattaccato: in uno studio su 25 persone la sutura teneva a 6 mesi.", "Il menisco si era comunque spostato un po' verso l'esterno, di più dove il tessuto era più alterato prima dell'intervento.", "Studio piccolo, senza risultati clinici: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42844718."]}, "instagram": {"chir": ["Radice mediale: T2* a 7 T ed estrusione.", "25 pazienti, estrusione da 3,7 a 4,9 mm con suture integre (p=0,002); T2* preoperatoria ρ=0,765.", "n=25, nessun esito clinico.\nFonte: PubMed, PMID 42844718."], "misto": ["Il menisco riattaccato può spostarsi.", "In 25 persone la sutura teneva, ma il menisco si era spostato di 1,2 mm in media.", "Studio piccolo, senza risultati clinici.\nFonte: PubMed, PMID 42844718."], "pazienti": ["Il menisco riattaccato può spostarsi.", "In uno studio su 25 persone la sutura teneva a 6 mesi, ma il menisco si era spostato un po'.", "Studio piccolo: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42844718."]}, "reel": {"chir": ["Radice mediale e T2*.", "Estrusione da 3,7 a 4,9 mm, suture integre.", "n=25, nessun esito clinico."], "misto": ["Menisco riattaccato.", "La sutura teneva, il menisco si è spostato.", "Studio piccolo."], "pazienti": ["Menisco riattaccato.", "La sutura teneva, ma si è spostato un po'.", "Studio piccolo."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Menisco #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #menisco #radicemeniscale #sutura #risonanzamagnetica #chirurgiaartroscopica #chirurgiaortopedica #ortopediaticino #medicinabasatasulleprove", "kw": "radice del menisco, sutura meniscale, risonanza magnetica, estrusione meniscale"}};
var NLB={"1": {"prof": ["Radice mediale: la T2* a 7 T prima della sutura è correlata all'estrusione dopo", "Un gruppo del Minnesota con LaPrade (J Orthop Res, ottobre 2026) ha studiato con risonanza a 7 tesla 25 pazienti prima e 6 mesi dopo la rifissazione della radice posteriore del menisco mediale, più 9 controlli. Le suture risultano integre in tutti, ma l'estrusione mediale aumenta da 3,7 ± 1,1 a 4,9 ± 1,5 mm (p=0,002) e la T2* preoperatoria correla con l'estrusione postoperatoria (ρ=0,765; p<0,001).", "Nota critica: 25 pazienti in una sola sede, estrusione a 6 mesi come unico esito, nessun esito clinico nell'abstract, tecnica di sutura non riportata e risonanza a 7 T non disponibile nella pratica corrente; l'intervallo di confidenza della correlazione non è riportato (stima mia: circa 0,53-0,89)."], "mix": ["Menisco: com'è il tessuto prima dell'intervento può contare per quanto si sposta dopo", "Quando si rompe la radice posteriore del menisco interno, il menisco si sposta verso l'esterno e si può riattaccarlo con una sutura. In uno studio con risonanza ad altissimo campo su 25 pazienti, le suture risultano integre a 6 mesi in tutti, eppure il menisco si sposta in media di più, da 3,7 a 4,9 millimetri. Più il tessuto appare alterato alla risonanza prima dell'intervento, maggiore è questo spostamento.", "Nota sul limite: sono pochi pazienti, in un solo centro, con un controllo a soli 6 mesi; lo studio non dice come stanno dopo ginocchio e dolore e non dimostra che si possa evitare lo spostamento."], "paz": ["Menisco riattaccato: il tessuto di partenza può contare", "Il menisco ha dei legamenti, le radici, che lo tengono al suo posto. Quando una si rompe si può riattaccare con una sutura. In uno studio su 25 persone la sutura teneva dopo 6 mesi, ma il menisco si era comunque spostato un po' verso l'esterno, tanto più quanto il suo tessuto appariva alterato prima dell'intervento.", "Lo studio è piccolo, dura pochi mesi e non dice come stanno le persone dopo; se ne parla con il chirurgo, caso per caso."], "kw": "radice del menisco, sutura meniscale, risonanza magnetica, estrusione meniscale"}, "2": {"prof": ["Sutura meniscale o meniscectomia con il LCA: nessuna differenza funzionale a circa 4 anni", "Una coorte retrospettiva di Pechino (Orthop Surg, ottobre 2026) su 52 pazienti molto attivi operati di LCA (Tegner prelesionale ≥6) confronta sutura meniscale (n=20) e meniscectomia parziale (n=32) a 4,1 ± 1,2 e 4,2 ± 1,2 anni: nessuna differenza in simmetria di forza di quadricipite e flessori, Y-balance, test di salto, IKDC, Lysholm e ACL-RSI (tutti p>0,05).", "Nota critica: gruppi piccoli, valori e intervalli di confidenza non riportati e «nessuna differenza» non è equivalenza; 5 pazienti su 68 esclusi per revisione o procedure meniscali secondarie possono essere proprio le suture fallite; il lavoro non misura la cartilagine."], "mix": ["Menisco suturato o asportato durante l'operazione al crociato: dopo 4 anni la funzione è simile", "In uno studio su 52 persone molto attive operate al legamento crociato, alcune avevano avuto il menisco ricucito (20) e altre in parte asportato (32). A circa 4 anni forza dei muscoli, equilibrio, salti e punteggi di funzione riferiti dai pazienti non mostravano differenze, anche se dopo la sutura la riabilitazione iniziale è più prudente.", "Nota sul limite: i gruppi sono piccoli e non assegnati a caso, e chi ha avuto problemi o nuove operazioni (5 persone su 68) è stato escluso; lo studio non guarda la salute della cartilagine negli anni, che è il motivo per cui si cerca di conservare il menisco."], "paz": ["Menisco ricucito o in parte asportato: la funzione dopo qualche anno è simile", "Quando durante l'intervento al crociato si trova anche una lesione del menisco, si può ricucirlo oppure asportarne la parte rotta. In uno studio su 52 persone molto attive, dopo circa 4 anni forza, equilibrio e salti erano simili nei due gruppi.", "Lo studio è piccolo e non misura la salute dell'articolazione sul lungo periodo: la scelta si discute con il chirurgo."], "kw": "sutura del menisco, menisco e legamento crociato, meniscectomia, ricostruzione del LCA"}, "3": {"prof": ["Fettuccia di sutura nel LCA di revisione: un commento che chiede coorti più grandi o un RCT", "Un editoriale su Arthroscopy (Lizzio, Tramer, Khalil, ottobre 2026) discute la suture tape augmentation nella revisione del LCA: per gli innesti di tessuto molle soggetti a cedimento può avere un ruolo, ma accanto contano scelta dell'innesto, tunnel, allineamento, lesioni meniscali e legamentose associate e la procedura laterale extra-articolare.", "Nota critica: è un'opinione senza dati propri e la raccomandazione è condizionale («se esiti e complicanze sono simili con meno re-rotture»); lo studio commentato non è identificato nell'abstract."], "mix": ["Rifare il crociato dopo un fallimento: un commento sulla fettuccia di rinforzo", "Quando un legamento crociato ricostruito cede e va rifatto, si cerca di cambiare qualcosa la seconda volta. Un commento pubblicato su Arthroscopy discute l'uso di una fettuccia di sutura come rinforzo del tendine, soprattutto quando si usa un tendine morbido, e ricorda che contano anche la posizione dei tunnel, l'allineamento della gamba, i menischi e un'eventuale procedura laterale.", "Nota sul limite: è l'opinione di tre autori, non uno studio sui pazienti, e per sapere se il rinforzo riduca davvero le nuove rotture servono studi più grandi."], "paz": ["Rifare il legamento crociato: un commento su un possibile rinforzo", "Se un legamento crociato ricostruito cede, si può operare di nuovo. Un commento di specialisti discute se rinforzare il nuovo tendine con una fettuccia di sutura, accanto ad altri aspetti da curare, come la posizione dei tunnel e lo stato dei menischi.", "È un parere di esperti, non uno studio su pazienti: la scelta si valuta con il chirurgo, caso per caso."], "kw": "legamento crociato anteriore, revisione del crociato, fettuccia di sutura, nuova rottura"}, "4": {"prof": ["Osteotomia tibiale aperta: il carico laterale sale al 45,8%, sotto la parità, in un modello a elementi finiti", "Uno studio di Kyoto (J Orthop Sci, ottobre 2026) su 40 ginocchia di 34 pazienti con artrosi mediale, con modelli paziente-specifici da TAC, mostra che dopo osteotomia tibiale ad apertura mediale l'asse meccanico percentuale va da 17,2% a 57,9% e la quota di carico laterale da 27,9% a 45,8% (p<0,001), senza più stress laterale di picco. Per arrivare al 50% l'asse stimato è 60,5%, 63,0% e 68,8% per K-L ≤2, 3 e 4.", "Nota critica: è un modello, non un esito clinico; il bersaglio pianificato (60,0-62,5%) non è stato raggiunto in media, le ginocchia non sono indipendenti, solo 6 sono K-L 4 e le soglie ROC sono esplorative; intervalli di confidenza non riportati."], "mix": ["Osteotomia della tibia: dopo l'intervento il carico passa al lato esterno, ma non a metà", "In uno studio giapponese su 40 ginocchia con usura del lato interno, un modello al computer costruito dalle TAC dei pazienti mostra che, dopo l'osteotomia che riallinea la gamba, la parte di peso sul lato esterno passa dal 28% al 46% circa, senza picchi di pressione maggiori. Per arrivare al 50% servirebbe un riallineamento più spinto, tanto più quanto l'artrosi è avanzata.", "Nota sul limite: è una simulazione al computer, non il risultato dei pazienti, e non dice come sia andata la riabilitazione né il dolore."], "paz": ["Osteotomia della tibia: come cambia il peso sul ginocchio", "Quando il ginocchio è consumato sul lato interno si può correggere l'asse della gamba con un taglio nell'osso. Uno studio giapponese su 40 ginocchia, con simulazioni al computer, mostra che dopo l'intervento una parte maggiore del peso passa al lato esterno.", "È una simulazione e non racconta come stanno le persone dopo l'operazione: la scelta si discute con il chirurgo."], "kw": "osteotomia tibiale alta, artrosi del ginocchio, allineamento della gamba, carico sul ginocchio"}, "5": {"prof": ["Protesi monocompartimentale mediale: il recupero lento nei primi 6 mesi anticipa il peggioramento fino a 5 anni", "Una coorte monocentrica di Pechino (J Arthroplasty, ottobre 2026) su 207 UKA mediali ha derivato traiettorie di dolore e funzione a 1, 3 e 6 mesi: l'analgesia lenta (17,9%) si associa a progressione del dolore fra 1 e 5 anni (aRR 2,41; p<0,001, probabilità stimata 88,2%), mentre miglioramento rapido (aRR 0,25) e recupero in rincorsa (0,16) riducono il rischio di declino funzionale (p<0,001).", "Nota critica: intervalli di confidenza non riportati; le traiettorie sono classi statistiche e le probabilità sono del modello; non è dichiarato se i dati fossero prospettici né quante perdite ci siano state; gli esiti sono punteggi, non revisioni."], "mix": ["Protesi parziale del ginocchio: come si sta nei primi mesi dice qualcosa sugli anni successivi", "In uno studio su 207 persone con protesi parziale del ginocchio, chi nei primi tre-sei mesi recupera lentamente dal dolore ha più probabilità di avere un peggioramento fra il primo e il quinto anno; chi migliora in fretta, o chi parte piano ma recupera, ha meno probabilità di perdere funzione.", "Nota sul limite: lo studio non dice se intervenire sul recupero lento cambi l'esito; i numeri sono stime di un modello statistico, in un solo ospedale, e mancano gli intervalli di confidenza."], "paz": ["Protesi parziale del ginocchio: i primi mesi possono essere un indizio", "In uno studio su 207 persone con protesi parziale, chi stava meglio già nei primi mesi tendeva a mantenere il risultato nei cinque anni successivi, mentre chi recuperava lentamente aveva più probabilità di avere di nuovo dolore.", "È un'osservazione su un gruppo e non una previsione per la singola persona: i controlli si decidono con il chirurgo."], "kw": "protesi monocompartimentale, protesi parziale del ginocchio, recupero dopo protesi, dolore dopo protesi"}, "6": {"prof": ["Radice posteriore del menisco laterale: una revisione narrativa su diagnosi e rifissazione, senza dati di esito", "Una revisione narrativa (Cureus, settembre 2026) di autori polacchi passa in rassegna anatomia, biomeccanica, classificazione, diagnosi e trattamento delle lesioni della radice posteriore del menisco laterale, con attenzione alla loro frequente associazione con il LCA acuto e alla rifissazione anatomica.", "Nota critica: l'abstract non dichiara metodo di ricerca né riporta dati di esito o intervalli di confidenza; non stima l'efficacia della riparazione e non indica una tecnica preferita; testo completo non letto."], "mix": ["Radice del menisco esterno: una rassegna su come riconoscerla e ripararla", "La radice posteriore del menisco esterno è il punto in cui il menisco si ancora all'osso della tibia. Una rassegna della letteratura ricorda che la sua lesione si associa spesso alla rottura acuta del legamento crociato e che, se non riconosciuta, può compromettere stabilità e conservazione del menisco; descrive anche la riparazione anatomica.", "Nota sul limite: è una rassegna senza metodo di ricerca dichiarato e senza numeri nel riassunto; non dice quanto funzioni la riparazione."], "paz": ["Menisco esterno: la radice che lo tiene all'osso", "Il menisco è ancorato alla tibia da due radici. Una rassegna di specialisti spiega che la rottura della radice del menisco esterno si trova spesso insieme alla rottura del legamento crociato e che va riconosciuta, perché può incidere sulla stabilità del ginocchio.", "È un riassunto della letteratura senza dati sui risultati: ogni decisione si prende con il chirurgo, caso per caso."], "kw": "menisco esterno, radice meniscale, lesione del menisco, legamento crociato"}, "7": {"prof": ["Frattura arcuata della testa del perone: riduzione a due tunnel con FiberTape dopo fallimento dell'ancora", "Una nota tecnica di Pristina e Belluno (SICOT-J, ottobre 2026) descrive la fissazione dell'avulsione della testa del perone, segno radiografico di lesione dell'angolo postero-laterale, con due tunnel fibulari e passaggio di FiberTape dopo il fallimento di una riparazione con ancora. Gli autori indicano come vantaggi il basso profilo, la riproducibilità e il costo iniziale più basso, e come criticità una possibile tensione disuguale.", "Nota critica: nessun paziente, nessun esito, nessun intervallo di confidenza; «affidabile ed efficace» è un'affermazione degli autori senza dati nell'abstract; testo completo non letto."], "mix": ["Distacco della testa del perone: una tecnica con due tunnel e una fettuccia di sutura", "Quando la testa del perone, l'osso esterno della gamba sotto il ginocchio, viene strappata dai legamenti dell'angolo posteriore esterno, va rifissata. Chirurghi del Kosovo e dell'Italia descrivono una tecnica con due piccoli tunnel nell'osso e una fettuccia di sutura, per i casi in cui una riparazione con ancora non ha tenuto.", "Nota sul limite: è la descrizione di una tecnica, senza pazienti né risultati; non dice quanto spesso funzioni."], "paz": ["Distacco dell'osso esterno sotto il ginocchio: una tecnica per rifissarlo", "A volte un trauma stacca un frammento dell'osso esterno della gamba, sotto il ginocchio, dove si attaccano i legamenti. Dei chirurghi descrivono come rifissarlo con due piccoli tunnel e una fettuccia di sutura quando una prima riparazione non ha tenuto.", "È la descrizione di una tecnica, senza risultati su pazienti: la scelta spetta al chirurgo, caso per caso."], "kw": "angolo postero-laterale, testa del perone, frattura arcuata, lesione del legamento"}, "8": {"prof": ["Sindrome della bandelletta ileo-tibiale: 24 studi e nessuna scelta dimostrata fra i trattamenti", "Una revisione sistematica di Humanitas (Orthop Res Rev, ottobre 2026) su 24 studi e 1012 pazienti trova miglioramenti in tutte le categorie di trattamento, ma eterogeneità diagnostica e metodologica impedisce di raccomandarne una sulle altre; un solo trial controllato adeguatamente potente sostiene il PRP ecoguidato nella forma refrattaria, la chirurgia è livello IV e la riabilitazione strutturata resta il primo passo.", "Nota critica: nessuna sintesi quantitativa né dimensioni dell'effetto nell'abstract; il livello di evidenza descrive il disegno e non l'entità dell'effetto; il PRP poggia su una prova non replicata in modo indipendente."], "mix": ["Dolore laterale del ginocchio nei corridori: molte cure, poche prove per scegliere", "La sindrome della bandelletta ileo-tibiale, una causa frequente di dolore sul lato esterno del ginocchio in chi corre, è stata esaminata in 24 studi su 1012 pazienti. Esercizi, terapia manuale, infiltrazioni e altre cure riportano miglioramenti, ma gli studi sono troppo diversi tra loro per dire quale sia la scelta migliore; per la forma che non guarisce c'è un solo studio controllato, sul PRP.", "Nota sul limite: la revisione non confronta i numeri fra le cure e segnala che mancano criteri diagnostici condivisi."], "paz": ["Dolore sul lato esterno del ginocchio nei corridori: la riabilitazione è il primo passo", "Una revisione di 24 studi su oltre mille persone conclude che, per il dolore laterale del ginocchio di chi corre, esercizi e riabilitazione strutturata sono un primo passo ragionevole; per i casi che non guariscono esistono altre opzioni, ma le prove per sceglierne una sono ancora poche.", "Si tratta di una sintesi della letteratura e non di una indicazione per la singola persona: la scelta si discute con il medico."], "kw": "bandelletta ileo-tibiale, dolore laterale del ginocchio, corridori, riabilitazione"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"J Orthop Res",h:"Radice mediale: la T2* prima della sutura prevede l'estrusione dopo",v:"Coorte di 25 pazienti con rifissazione della radice posteriore del menisco mediale, risonanza a 7 tesla prima e a 6 mesi: suture integre in tutti, ma l'estrusione mediale sale da 3,7 ± 1,1 a 4,9 ± 1,5 mm (p=0,002) e la T2* preoperatoria è correlata all'estrusione dopo (ρ=0,765; p<0,001). Esiti clinici non riportati nell'abstract.",ax:"Kajabi, Knutsen, Hedayati, Steinberger, Zbýň, Hassan, Ahad, Lamba, Tollefson, Takahashi, Metzger, LaPrade, Ellermann",date:"ott 2026",meta:"coorte con controlli, 25 pazienti e 9 controlli, risonanza a 7 T · [III per disegno]",pmid:'42844718',doi:'10.1002/jor.70286',journal:"Journal of orthopaedic research",authors:"Kajabi AW, Knutsen K, Hedayati E, Steinberger C, Zbýň Š, Hassan AA, Ahad H, Lamba A, Tollefson LV, Takahashi T, Metzger GJ, LaPrade RF, Ellermann JM",design:"Studio di imaging dell'Università del Minnesota (Center for Magnetic Resonance Research) con Twin Cities Orthopedics e Cleveland Clinic: 25 pazienti con lesione della radice posteriore del menisco mediale studiati con risonanza a 7 tesla prima della rifissazione e a 6 mesi, più 9 controlli di pari età e sesso scansionati una volta. La mappa 3D T2* dei menischi è confrontata con l'estrusione misurata da due radiologi sulle immagini coronali T2. Livello di evidenza non dichiarato (III per disegno: coorte con controlli). Testo completo non aperto: contenuto dall'abstract.",pop:"25 pazienti, età media 53 ± 8 anni; 9 controlli di 51 ± 11 anni, appaiati per età e sesso. Ripartizione per sesso, tecnica di sutura e riabilitazione non riportate nell'abstract. Follow-up: 6 mesi.",results:"Suture integre alla risonanza in tutti i 25 pazienti. T2* più alta nei pazienti che nei controlli, sia prima sia dopo la sutura, in tutte le sottoregioni dei menischi mediale e laterale (valori non riportati nell'abstract). Estrusione mediale da 3,7 ± 1,1 mm a 4,9 ± 1,5 mm (p=0,002). T2* preoperatoria contro estrusione postoperatoria: ρ=0,765 (p<0,001); l'intervallo di confidenza non è nell'abstract (stima mia con la trasformata di Fisher su n=25, non dato degli autori: circa 0,53-0,89). Esiti clinici non riportati nell'abstract.",concl:"Gli autori: la T2* a 7 T resta elevata dopo la sutura, coerente con una disorganizzazione persistente delle fibre di collagene, e il valore prima della sutura si associa all'estrusione precoce nonostante riparazioni integre; la qualità del tessuto preoperatorio sarebbe quindi associata all'esito, e la T2* un biomarcatore prognostico che completa la risonanza morfologica.",limits:"25 pazienti e una sola sede · l'estrusione a 6 mesi è un esito intermedio: esiti clinici e progressione dell'artrosi non sono nell'abstract · è una correlazione fra due misure nello stesso gruppo: non prova che la T2* causi l'estrusione né che cambiare tecnica la eviti · tecnica di sutura, ancoraggio e riabilitazione non riportati · la risonanza a 7 T non è disponibile nella pratica corrente, quindi si trasferisce il concetto, non il test · il confronto con i controlli non è un confronto di esito.",perte:"È la tua indicazione (rifissazione della radice mediale), ma l'abstract non dice con quale tecnica sono state suturate: non posso dire che sia la transtibiale pull-out. Per T2b il dato che conta è che l'estrusione cresce di circa 1,2 mm in 6 mesi pur con riparazioni integre: l'estrusione resta il problema aperto anche con la sutura riuscita, e compare un candidato predittore preoperatorio (qualità del tessuto) che oggi non si misura in ambulatorio. Non chiude la tensione: nessun confronto fra tecniche, follow-up di 6 mesi."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Orthop Surg",h:"Sutura meniscale o meniscectomia con il LCA: a 4 anni stessa funzione",v:"Coorte retrospettiva di 52 pazienti molto attivi operati di LCA (Tegner prelesionale ≥6): sutura meniscale (n=20) contro meniscectomia parziale (n=32), follow-up 4,1 ± 1,2 e 4,2 ± 1,2 anni (p=0,59). Nessuna differenza in forza isocinetica, Y-balance, salti e punteggi riferiti (tutti p>0,05); valori e intervalli di confidenza non riportati nell'abstract.",ax:"Duan, Zhang, Sun, Zhang, Li, Zhou",date:"ott 2026",meta:"coorte retrospettiva comparativa, 52 pazienti in 2 gruppi · [III per disegno]",pmid:'42849477',doi:'10.1111/os.70419',journal:"Orthopaedic surgery",authors:"Duan H, Zhang H, Sun J, Zhang X, Li T, Zhou J",design:"Coorte retrospettiva del Beijing Chaoyang Hospital: pazienti operati di LCA fra il 2019 e il 2023 con lesione meniscale concomitante e Tegner prelesionale ≥6. Dei 68 identificati, 16 esclusi (5 per revisione del LCA o procedure meniscali secondarie nel follow-up, 8 per multilegamentose o difetti condrali da operare, 3 per deformità in varo o valgo >5°); i 52 rimasti sono divisi fra sutura (20) e meniscectomia parziale (32). Esiti: forza isocinetica a 60°/s e 180°/s (LSI), Y-balance, tre test di salto, IKDC, Lysholm, ACL-RSI. Livello non dichiarato. Testo completo non aperto: contenuto dall'abstract.",pop:"52 pazienti molto attivi (Tegner prelesionale ≥6); età, sesso, innesto e tecnica di sutura non riportati nell'abstract. Follow-up medio 4,1 ± 1,2 anni (sutura) e 4,2 ± 1,2 anni (meniscectomia).",results:"A 2-5 anni nessuna differenza significativa fra i gruppi nel rapporto di simmetria (LSI) di quadricipite e flessori a 60°/s e 180°/s, nel Y-balance, nei tre test di salto, in IKDC, Lysholm e ACL-RSI (tutti p>0,05); durata del follow-up simile (p=0,59). Valori, differenze e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: a medio termine la sutura dà funzione e punteggi equivalenti alla meniscectomia, nonostante la riabilitazione iniziale più restrittiva; l'analisi riguarda solo la parità funzionale, e la scelta va pesata anche sulla salute articolare a lungo termine.",limits:"20 contro 32 pazienti e nessun intervallo di confidenza: «nessuna differenza» non è equivalenza · 5 pazienti su 68 esclusi per revisione del LCA o procedure meniscali secondarie nel follow-up: se fra loro ci sono suture fallite, il gruppo sutura è composto da casi riusciti e il confronto è sbilanciato a suo favore · gruppi non assegnati a caso; tipo di lesione e di sutura non riportati · la funzione non misura la protezione della cartilagine, che è la ragione per cui si sutura.",perte:"Fai la sutura meniscale con il LCA nell'intervento standard: qui c'è una conferma muta che la riabilitazione più restrittiva non lascia deficit funzionali a medio termine. Innesto e tecnica di sutura non sono nell'abstract, quindi non so se coincidono con retto femorale più LET; il dato non tocca nessuna tensione aperta."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Fettuccia di sutura nel LCA di revisione: un commento che chiede un trial",v:"Editoriale di opinione su Arthroscopy: l'augmentation con suture tape può servire nella revisione del LCA, soprattutto con innesti di tessuto molle soggetti a cedimento, ma per isolarne l'effetto servono coorti più grandi o un RCT. Nessun dato proprio. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Lizzio, Tramer, Khalil",date:"ott 2026",meta:"editoriale, nessun dato proprio · [V]",pmid:'42848314',doi:'10.1002/arj.70677',journal:"Arthroscopy",authors:"Lizzio VA, Tramer JS, Khalil LS",design:"Commento editoriale (Editorial Commentary) a uno studio sulla suture tape augmentation nel LCA di revisione; l'abstract non identifica lo studio commentato. Nessun gruppo, nessuna misura. Livello V per tipologia. Testo completo non aperto: contenuto dall'abstract.",pop:"Nessun paziente: non riportato.",results:"Nessun dato di esito. Gli autori elencano come fattori noti di fallimento del primo LCA l'età giovane, il livello di attività elevato, il diametro piccolo dell'innesto e lo slope tibiale aumentato; per la revisione ricordano che contano anche scelta dell'innesto, posizione dei tunnel, allineamento, lesioni meniscali e legamentose associate e l'aggiunta di una procedura laterale extra-articolare. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: se l'augmentation dimostra esiti e complicanze simili con meno re-rotture, può valere la pena adottarla già ora nella revisione; per stabilirlo servono coorti più grandi o un RCT.",limits:"Opinione di esperti, senza dati propri · lo studio commentato non è identificato nell'abstract · l'abstract non dice quale innesto né quale fettuccia · la raccomandazione è condizionale («se dimostra…»), non un risultato.",perte:"Tocca due cose tue: gli innesti di tessuto molle in revisione (il retto femorale lo è) e la procedura laterale extra-articolare, citata fra i fattori da considerare. Non indica che la suture tape sostituisca il LET né che i due si sommino; nessuna tensione si muove."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"J Orthop Sci",h:"Osteotomia tibiale aperta: il carico passa al lato laterale, ma non arriva al 50%",v:"Analisi agli elementi finiti su 40 ginocchia di 34 pazienti dopo osteotomia tibiale ad apertura mediale: l'asse meccanico percentuale va da 17,2% a 57,9% (bersaglio 60,0-62,5%) e la quota di carico laterale da 27,9% a 45,8% (p<0,001), senza più stress laterale di picco; per raggiungere il 50% serve un asse di 60,5%, 63,0% o 68,8% secondo il grado K-L (≤2, 3, 4). Intervalli di confidenza non riportati nell'abstract.",ax:"Morita, Kuriyama, Yamawaki, Sakai, Nishitani, Nakamura, Matsuda",date:"ott 2026",meta:"analisi agli elementi finiti paziente-specifica, 40 ginocchia (34 pazienti) · [IV per disegno]",pmid:'42850104',doi:'10.1016/j.jos.2026.09.013',journal:"Journal of orthopaedic science",authors:"Morita Y, Kuriyama S, Yamawaki Y, Sakai S, Nishitani K, Nakamura S, Matsuda S",design:"Studio di Kyoto (Università e ospedali affiliati) su 40 ginocchia di 34 pazienti con artrosi del compartimento mediale (K-L ≤2 in 18, 3 in 16, 4 in 6) operati di osteotomia tibiale ad apertura mediale con bersaglio di asse meccanico percentuale 60,0-62,5%. Modelli agli elementi finiti paziente-specifici costruiti da TAC preoperatoria e da TAC a un anno dalla rimozione del mezzo di sintesi, con densità ossea; forze di contatto e rapporto laterale/totale correlati ad asse, apertura e KOOS. Serie senza gruppo di confronto clinico: i risultati dipendono dalle ipotesi del modello. Livello non dichiarato. Testo completo non aperto: contenuto dall'abstract.",pop:"40 ginocchia in 34 pazienti con artrosi mediale (K-L ≤2: 18; 3: 16; 4: 6); età e sesso non riportati nell'abstract. TAC postoperatoria a 1-2 settimane e a un anno dalla rimozione del mezzo di sintesi.",results:"Asse meccanico percentuale da 17,2% a 57,9%. Forza di contatto mediale da 415,4 a 320,9 N, laterale da 157,1 a 268,6 N, rapporto laterale/totale da 27,9% a 45,8% (tutti p<0,001), senza aumento dello stress laterale di picco. L'asse postoperatorio correla con il trasferimento laterale; un'apertura più ampia, che riflette la correzione richiesta, si associa a meno trasferimento. La forza di contatto laterale correla con KOOS sintomi e attività quotidiane. Valori esplorativi (ROC): asse 59,4% e apertura 9,5 mm; asse stimato per un rapporto ≥50%: 60,5%, 63,0% e 68,8% per K-L ≤2, 3 e 4. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: l'osteotomia sposta il carico lateralmente senza aumentare lo stress laterale di picco; un asse postoperatorio più alto si associa a più trasferimento; l'apertura è un indicatore della correzione richiesta, non una causa; negli stadi avanzati i bersagli di allineamento potrebbero essere individualizzati.",limits:"Modello numerico: i risultati valgono per le ipotesi del modello e non sono esiti clinici · il bersaglio pianificato (60,0-62,5%) non è stato raggiunto in media (57,9%) · 40 ginocchia di 34 pazienti, quindi non indipendenti; solo 6 ginocchia K-L 4 · soglie ROC dichiarate esplorative e non validate · il rapporto laterale/totale del 50% è un criterio scelto dagli autori, non uno standard di buon esito · intervalli di confidenza e esiti clinici non riportati nell'abstract.",perte:"Fai osteotomie correttive, slope compreso: questo lavoro riguarda l'apertura mediale sul piano frontale e non tocca lo slope. Utile come ordine di grandezza per il bersaglio di allineamento secondo il grado di artrosi, ma è biomeccanica da modello e non dice come stanno i pazienti dopo; nessuna tensione si muove."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"J Arthroplasty",h:"UKA mediale: il recupero lento nei primi 6 mesi anticipa il declino fra 1 e 5 anni",v:"Coorte monocentrica di 207 protesi monocompartimentali mediali: dolore e funzione a 1, 3 e 6 mesi tracciano traiettorie. Il 17,9% con analgesia lenta ha una probabilità stimata dell'88,2% di progressione del dolore fra 1 e 5 anni (aRR 2,41; p<0,001); miglioramento rapido (aRR 0,25) e recupero in rincorsa (0,16) riducono il rischio di declino funzionale (p<0,001). Intervalli di confidenza non riportati nell'abstract.",ax:"Wang, Du, Cao, Huang",date:"ott 2026",meta:"coorte monocentrica, 207 pazienti, modelli di traiettoria · [III per disegno]",pmid:'42843678',doi:'10.1016/j.arth.2026.09.045',journal:"The Journal of arthroplasty",authors:"Wang Z, Du M, Cao G, Huang Y",design:"Coorte monocentrica del Beijing Jishuitan Hospital (reparto di preservazione del ginocchio): 207 pazienti con UKA mediale primaria operati fra gennaio 2016 e gennaio 2021, con NRS e Oxford Knee Score prima dell'intervento e a 1, 3 e 6 mesi, poi a 1, 2 e 5 anni. Growth mixture modeling per le traiettorie; regressione di Poisson modificata, ponderata per la probabilità a posteriori, per collegare le traiettorie precoci a quelle tardive (rischio relativo aggiustato, aRR). Se i dati siano stati raccolti in prospettiva: non dichiarato nell'abstract. Livello non dichiarato. Testo completo non aperto: contenuto dall'abstract.",pop:"207 pazienti con UKA mediale primaria, 2016-2021; età, sesso, indicazione, impianto e perdite al follow-up non riportati nell'abstract. Follow-up fino a 5 anni.",results:"Traiettorie precoci del dolore: analgesia lenta 17,9%, rapida 82,1%. Funzione (OKS): miglioramento rapido 37,2%, recupero in rincorsa 37,2%, miglioramento lento 25,6%. Fra 1 e 5 anni: progressione del dolore 34,8% contro dolore basso stabile 65,2%; declino funzionale 24,6% contro funzione mantenuta 75,4%. Probabilità stimate di transizione: 88,2% di progressione del dolore dopo analgesia lenta; 70,4% di declino funzionale dopo miglioramento lento. aRR di progressione del dolore con analgesia lenta 2,41 (p<0,001); aRR di declino funzionale rispetto al miglioramento lento: 0,25 con miglioramento rapido e 0,16 con recupero in rincorsa (p<0,001). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: traiettorie precoci sfavorevoli di dolore e funzione identificano i pazienti con maggior rischio di peggioramento dei punteggi fra 1 e 5 anni; il monitoraggio precoce può essere un segnale d'allarme pratico per una sorveglianza più stretta e una gestione mirata.",limits:"Monocentrico, senza intervalli di confidenza nell'abstract · le traiettorie sono classi statistiche stimate dai dati, non gruppi osservati: l'88,2% è una probabilità del modello · non è dichiarato se i dati siano stati raccolti in prospettiva né quanti pazienti si siano persi fra 1 e 5 anni · gli esiti sono punteggi riferiti dal paziente, non revisioni né sopravvivenza dell'impianto · l'associazione non dice che intervenire sul recupero lento cambi l'esito.",perte:"Fai la UKA, quindi la popolazione è la tua; impianto e tecnica non sono nell'abstract. Spunto pratico: dolore e OKS a 1-6 mesi come segnale per anticipare i controlli. Non è un test validato da altri e non muove nessuna tensione."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Cureus",h:"Radice posteriore del menisco laterale: una revisione narrativa senza numeri",v:"Revisione narrativa su anatomia, biomeccanica, classificazione, diagnosi e trattamento delle lesioni della radice posteriore del menisco laterale, con attenzione all'associazione frequente con il LCA acuto e alla rifissazione anatomica. L'abstract non dichiara né un metodo di ricerca né dati di esito. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Boguszewski, Kopoczynski, Bartkowiak, Wiesner, Wodzinski, Jakubczyk, Lasota, Porazinski, Mlynarska, Ratajski",date:"set 2026",meta:"revisione narrativa, nessun dato di esito nell'abstract · [V per tipologia]",pmid:'42841079',doi:'10.7759/cureus.115860',journal:"Cureus",authors:"Boguszewski K, Kopoczynski L, Bartkowiak D, Wiesner M, Wodzinski L, Jakubczyk B, Lasota A, Porazinski H, Mlynarska A, Ratajski O",design:"Revisione narrativa di autori di ospedali polacchi (Bydgoszcz, Gdynia, Malbork, Wejherowo e altri) su anatomia, biomeccanica, classificazione, epidemiologia, diagnosi e trattamento delle lesioni della radice posteriore del menisco laterale, con confronto con la radice mediale. L'abstract non dichiara metodo di ricerca, numero di studi né criteri di inclusione. Livello V per tipologia. Testo completo presente su PMC ma non letto: contenuto dall'abstract.",pop:"Nessuna popolazione propria: revisione della letteratura.",results:"Nessun dato quantitativo nell'abstract. La revisione tratta riparazione artroscopica anatomica della radice, tecniche di riparazione, fattori che orientano la scelta del trattamento, riabilitazione, complicanze ed esiti, e sottolinea la coesistenza frequente con lesioni acute del LCA e le conseguenze, per stabilità e conservazione del menisco, di una lesione non riconosciuta o non trattata. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: sintetizzano aree di consenso, limiti della letteratura e priorità di ricerca per diagnosi, trattamento ed esiti; l'abstract non dà una raccomandazione operativa.",limits:"Narrativa senza metodo di ricerca dichiarato né sintesi quantitativa: non stima quanto sia efficace la riparazione né la confronta con la meniscectomia · rivista generalista ad accesso aperto · testo completo non letto: classificazione e tecniche non verificate.",perte:"Rifissi la radice del menisco mediale con tecnica transtibiale; qui si parla del laterale, spesso associato al LCA acuto, cioè nel tuo caso tipico del crociato. L'abstract non dice quale tecnica di riparazione sia preferita, quindi non è direttamente trasferibile. Si affianca alla serie transtibiale sulla radice laterale già in T2b (1 ottobre); nessuna tensione si muove."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"SICOT-J",h:"Frattura arcuata della fibula: riduzione a due tunnel con FiberTape",v:"Nota tecnica su come fissare l'avulsione della testa del perone («arcuate sign», spia di lesione dell'angolo postero-laterale) dopo il fallimento di una riparazione con ancora: due tunnel nella fibula e passaggio di FiberTape. Nessun paziente, nessun esito. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Shabani, Musliu, Bytyqi, Ballis",date:"ott 2026",meta:"nota tecnica, nessun paziente analizzato · [V]",pmid:'42842897',doi:'10.1051/sicotj/2026052',journal:"SICOT-J",authors:"Shabani B, Musliu D, Bytyqi D, Ballis R",design:"Nota tecnica (indicizzata anche come case report) della Clinic of Orthopedics dello University Clinical Center of Kosovo (Pristina), con un coautore del reparto di Ortopedia e Traumatologia dell'Ospedale San Martino di Belluno: fissazione delle avulsioni della testa del perone con due tunnel nella fibula e FiberTape, dopo il fallimento di una riparazione con ancora. Nessun gruppo, nessuna misura di esito. Livello V per tipologia. Testo completo presente su PMC ma non letto: contenuto dall'abstract.",pop:"Nessun paziente analizzato nell'abstract: non riportato.",results:"Nessun dato di esito. Gli autori indicano come vantaggi una costruzione a basso profilo, riproducibile, con minima irritazione dei tessuti molli e costo iniziale dell'impianto più basso; riconoscono come criticità una possibile tensione disuguale delle suture. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il metodo è un'alternativa affidabile ed efficace per le avulsioni instabili, in particolare nelle lesioni complesse dell'angolo postero-laterale; servono altri studi per validare gli esiti a lungo termine.",limits:"Nessun paziente e nessun esito: «affidabile ed efficace» è un'affermazione degli autori, senza dati nell'abstract · il vantaggio di costo non è quantificato · la tecnica nasce per il fallimento di una riparazione con ancora, quindi il campo d'uso è ristretto · testo completo non letto: numero di casi, follow-up e materiali non verificati.",perte:"Non è una tua procedura dichiarata: l'angolo postero-laterale e le multilegamentose sono un tuo interesse, non una tua tecnica di routine. Usa una fettuccia di sutura passata in tunnel fibulari invece di un'ancora, a differenza del tuo MPFL con FiberTak. Nessuna tensione si muove."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Orthop Res Rev",h:"Bandelletta ileo-tibiale: l'eterogeneità impedisce di scegliere un trattamento",v:"Revisione sistematica di 24 studi e 1012 pazienti: tutte le categorie di trattamento riportano miglioramenti di dolore e funzione, ma eterogeneità diagnostica e metodologica impediscono di raccomandarne una sulle altre; un solo trial controllato adeguatamente potente sostiene il PRP ecoguidato (livello I, non replicato), la chirurgia è livello IV. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Ferrero, Moro, Minelli, Marcolin, Conte, Patrucco, D'Arrigo, Kon, Anzillotti",date:"ott 2026",meta:"revisione sistematica, 24 studi, 1012 pazienti · [IV per disegno]",pmid:'42841071',doi:'10.2147/ORR.S629195',journal:"Orthopedic research and reviews",authors:"Ferrero A, Moro A, Minelli M, Marcolin MG, Conte P, Patrucco F, D'Arrigo D, Kon E, Anzillotti G",design:"Revisione sistematica PRISMA 2020, protocollo registrato in PROSPERO (CRD420261374567), di Humanitas University e IRCCS Humanitas (Pieve Emanuele, Rozzano) con Kon: PubMed, Embase e Web of Science fino al 29 aprile 2026, più un trial successivo; RCT, coorti e serie in adulti con sindrome della bandelletta ileo-tibiale diagnosticata clinicamente; rischio di bias con RoB 2 e strumenti NIH; livelli di evidenza secondo CEBM. Sintesi non quantitativa. Testo completo presente su PMC ma non letto: contenuto dall'abstract.",pop:"24 studi, 1012 pazienti adulti con sindrome della bandelletta ileo-tibiale diagnosticata clinicamente; età e sesso non riportati nell'abstract.",results:"Dolore e funzione migliorano in tutte le categorie (esercizio, fisioterapia strumentale, terapia manuale e tecniche mini-invasive, infiltrazioni e farmaci, chirurgia). Livello I: terapia manuale, infiltrazioni farmacologiche o cortisoniche e PRP; livello Ib: esercizio terapeutico e fisioterapia strumentale; livello IV: chirurgia. Un solo trial controllato con placebo, adeguatamente potente, sostiene il PRP ecoguidato nella forma refrattaria; TECAR, laser a bassa intensità, prolozio e acido ialuronico non hanno prove controllate specifiche. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la riabilitazione strutturata resta il primo passo ragionevole; per la forma refrattaria il PRP ecoguidato è un'opzione promettente ma non ancora replicata in modo indipendente; infiltrazioni cortisoniche, terapie strumentali e chirurgia possono essere considerate in casi selezionati; servono criteri diagnostici standardizzati e confronti diretti.",limits:"Nessuna sintesi quantitativa: i trattamenti non si possono confrontare fra loro · eterogeneità estrema per diagnosi e protocolli, che gli autori attribuiscono alla letteratura più che alla revisione · il livello di evidenza descrive il disegno, non la dimensione dell'effetto · una sola prova per il PRP · testo completo non letto.",perte:"Fuori dalla tua pratica operatoria (dolore laterale del corridore, trattamento in larga parte conservativo): entra perché è nel perimetro del ginocchio e mostra quanto poco sostengano le prove ciascun trattamento. Nessuna tensione si muove."}];
var SUGGQ=[{"k": "kol", "n": "Jingbin Zhou (Beijing Chaoyang Hospital, Pechino, Cina)", "w": "Cina: ultimo autore dello studio di oggi su sutura meniscale contro meniscectomia con il LCA (PMID 42849477; afferenza letta nei metadati PubMed). Corrispondenza tecnica con la tua sutura meniscale nell'intervento al crociato. Sostituisce Simon Novak (8 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Oggi, venerdì 9 ottobre, otto lavori e nessuna scheda rossa né arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida. Il lavoro del giorno è uno studio del Minnesota, con LaPrade, sulla rifissazione della radice posteriore del menisco mediale: venticinque pazienti studiati con una risonanza a sette tesla prima dell'intervento e a sei mesi. Le suture risultano integre in tutti, ma l'estrusione mediale sale da tre virgola sette a quattro virgola nove millimetri, e il valore della sequenza T2 star prima della sutura è correlato all'estrusione dopo. L'abstract non dice con quale tecnica sono state suturate, quindi non posso dire che sia la tua transtibiale; non ci sono esiti clinici, il follow-up è di sei mesi e la risonanza a sette tesla non è disponibile nella pratica. Conferma che l'estrusione resta il problema aperto anche con la sutura riuscita, ma non chiude la tensione. Tra le altre schede: una coorte retrospettiva di Pechino su cinquantadue pazienti molto attivi non trova differenze di forza, equilibrio, salti e punteggi fra sutura meniscale e meniscectomia a circa quattro anni, ma i gruppi sono di venti e trentadue pazienti, non c'è equivalenza dimostrata e i pazienti rioperati sono stati esclusi. Un editoriale su Arthroscopy discute la fettuccia di sutura nel crociato di revisione, senza dati propri. Un modello a elementi finiti di Kyoto mostra che dopo l'osteotomia aperta la quota di carico laterale sale dal ventotto al quarantasei per cento circa, senza arrivare alla parità, ed è una simulazione, non un esito clinico. Una coorte di duecentosette protesi monocompartimentali mediali lega il recupero lento nei primi sei mesi al peggioramento fra uno e cinque anni, senza intervalli di confidenza nell'abstract. Completano una revisione narrativa sulla radice del menisco laterale, una nota tecnica kosovara sulla frattura arcuata della fibula, senza pazienti, e una revisione sistematica sulla bandelletta ileo-tibiale, che non permette di scegliere un trattamento. Per le proposte da seguire oggi il nome è Jingbin Zhou, di Pechino, per la sutura meniscale nell'intervento al crociato.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi, venerdì 9 ottobre: otto lavori, nessuna scheda rossa né arancione, nessun richiamo nuovo e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "E il lavoro del giorno?"}, {"chi": "A", "t": "Uno studio del Minnesota, con LaPrade, sulla rifissazione della radice posteriore del menisco mediale: venticinque pazienti con risonanza a sette tesla prima dell'intervento e a sei mesi."}, {"chi": "B", "t": "E cosa trovano?"}, {"chi": "A", "t": "Le suture sono integre in tutti, ma l'estrusione mediale sale da tre virgola sette a quattro virgola nove millimetri. E il valore della T2 star prima della sutura è correlato all'estrusione dopo."}, {"chi": "B", "t": "Quindi la sutura tiene e il menisco si sposta lo stesso. È la mia transtibiale?"}, {"chi": "A", "t": "L'abstract non lo dice: la tecnica di sutura non è riportata, quindi non posso affermarlo. Non ci sono esiti clinici e la risonanza a sette tesla non è disponibile in pratica."}, {"chi": "B", "t": "Quindi cosa me ne faccio?"}, {"chi": "A", "t": "Conferma che l'estrusione resta il problema aperto anche con la sutura riuscita, ma non chiude la tensione: è un solo centro e sei mesi."}, {"chi": "B", "t": "Altro sul menisco?"}, {"chi": "A", "t": "Una coorte di Pechino su cinquantadue pazienti molto attivi: sutura e meniscectomia danno la stessa funzione a circa quattro anni. Ma i gruppi sono di venti e trentadue, nessuna differenza non è equivalenza, e i rioperati sono stati esclusi."}, {"chi": "B", "t": "E le osteotomie?"}, {"chi": "A", "t": "Un modello di Kyoto: dopo l'osteotomia aperta il carico laterale passa dal ventotto al quarantasei per cento circa, ma è una simulazione, non un esito clinico."}, {"chi": "B", "t": "Quindi un ordine di grandezza per il bersaglio di allineamento, non una prova."}, {"chi": "A", "t": "Esatto. Come proposta da seguire oggi: Jingbin Zhou, di Pechino, per la sutura meniscale nell'intervento al crociato."}];
